n = int(input())
juices = []

for _ in range(n):
    c, s = input().split()
    c = int(c)
    # Convert vitamins to bitmask
    bitmask = 0
    if 'A' in s:
        bitmask |= 1
    if 'B' in s:
        bitmask |= 2
    if 'C' in s:
        bitmask |= 4
    juices.append((bitmask, c))

# Try one juice with all three vitamins
min_cost = float('inf')
for mask, cost in juices:
    if mask == 7:  # 111 in binary
        min_cost = min(min_cost, cost)

# Try two juices
# One with A and B (mask 3) and one with C (mask 4)
ab_cost = float('inf')
c_cost = float('inf')
for mask, cost in juices:
    if mask == 3:
        ab_cost = min(ab_cost, cost)
    if mask == 4:
        c_cost = min(c_cost, cost)
min_cost = min(min_cost, ab_cost + c_cost)

# One with A and C (mask 5) and one with B (mask 2)
ac_cost = float('inf')
b_cost = float('inf')
for mask, cost in juices:
    if mask == 5:
        ac_cost = min(ac_cost, cost)
    if mask == 2:
        b_cost = min(b_cost, cost)
min_cost = min(min_cost, ac_cost + b_cost)

# One with B and C (mask 6) and one with A (mask 1)
bc_cost = float('inf')
a_cost = float('inf')
for mask, cost in juices:
    if mask == 6:
        bc_cost = min(bc_cost, cost)
    if mask == 1:
        a_cost = min(a_cost, cost)
min_cost = min(min_cost, bc_cost + a_cost)

# Try three juices
# One with A (mask 1), one with B (mask 2), one with C (mask 4)
min_cost = min(min_cost, a_cost + b_cost + c_cost)

if min_cost == float('inf'):
    print(-1)
else:
    print(min_cost)
"}

