import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    q = int(data[1])
    ranges = []
    idx = 2

    for _ in range(q):
        l = int(data[idx])
        r = int(data[idx + 1])
        ranges.append((l, r))
        idx += 2

    max_covered = 0

    # Try all combinations of q-2 painters
    for mask in range(1 << q):
        if bin(mask).count('1') != q - 2:
            continue

        # Extract the ranges we hire
        hired_ranges = []
        for i in range(q):
            if mask & (1 << i):
                hired_ranges.append(ranges[i])

        # Merge ranges and count covered sections
        hired_ranges.sort()
        merged = []
        for l, r in hired_ranges:
            if not merged:
                merged.append((l, r))
            else:
                last_l, last_r = merged[-1]
                if l <= last_r:
                    merged[-1] = (last_l, max(last_r, r))
                else:
                    merged.append((l, r))

        total = 0
        for l, r in merged:
            total += r - l + 1

        max_covered = max(max_covered, total)

    print(max_covered)

if __name__ == "__main__":
    solve()
"}

