# If k > sqrt(n), we have more numbers than the maximum possible distinct remainders
# for the largest divisor, so duplicates must exist
if k > int(n ** 0.5):
    print("No")
else:
    # Check if all remainders are distinct
    remainders = set()
    for i in range(1, k + 1):
        r = n % i
        if r in remainders:
            print("No")
            break
        remainders.add(r)
    else:
        print("Yes")
"}

