def is_palindrome(s, l, r):
    while l < r:
        if s[l] != s[r]:
            return False
        l += 1
        r -= 1
    return True

s = input().strip()
length = len(s)

# List to store all palindromic substrings (start, end, length)
palindromes = []

# Check for odd-length palindromes
for i in range(length):
    l, r = i, i
    while l >= 0 and r < length and s[l] == s[r]:
        palindromes.append((l, r))
        l -= 1
        r += 1

# Check for even-length palindromes
for i in range(length - 1):
    l, r = i, i + 1
    while l >= 0 and r < length and s[l] == s[r]:
        palindromes.append((l, r))
        l -= 1
        r += 1

# Count valid pairs
count = 0
for i in range(len(palindromes)):
    start1, end1 = palindromes[i]
    for j in range(i + 1, len(palindromes)):
        start2, end2 = palindromes[j]
        if end1 < start2:
            count += 1

print(count)
"}

