def is_palindrome(s, l, r):
    while l < r:
        if s[l] != s[r]:
            return False
        l += 1
        r -= 1
    return True

s = input().strip()
length = len(s)

# List to store all unique palindromic substrings (start, end, length)
palindromes = []

# Check for odd-length palindromes
for i in range(length):
    l, r = i, i
    while l >= 0 and r < length and s[l] == s[r]:
        if not any((start == l and end == r) for (start, end) in palindromes):
            palindromes.append((l, r))
        l -= 1
        r += 1

# Check for even-length palindromes
for i in range(length - 1):
    l, r = i, i + 1
    while l >= 0 and r < length and s[l] == s[r]:
        if not any((start == l and end == r) for (start, end) in palindromes):
            palindromes.append((l, r))
        l -= 1
        r += 1

# Count valid pairs
# We need to count all pairs (i, j) where i < j and end of i-th palindrome < start of j-th palindrome
count = 0
for i in range(len(palindromes)):
    start_i, end_i = palindromes[i]
    # Find all j where j > i and palindromes[j] starts after palindromes[i] ends
    for j in range(i + 1, len(palindromes)):
        start_j, end_j = palindromes[j]
        if end_i < start_j:
            count += 1

print(count)
"}

