import sys
sys.setrecursionlimit(1000000)

from functools import lru_cache

@lru_cache(None)
def f(N):
    if N == 0:
        return 0
    take1 = 1 + g(N - 1)
    if N % 2 == 0:
        take_half = (N // 2) + g(N // 2)
        take1 = max(take1, take_half)
    return take1

@lru_cache(None)
def g(N):
    if N == 0:
        return 0
    take1 = f(N - 1)
    if N % 2 == 0:
        take_half = f(N // 2)
        take1 = min(take1, take_half)
    return take1

# Compute small N manually
small_N = [i for i in range(21)]
small_f = [f(i) for i in small_N]
small_g = [g(i) for i in small_N]

# Find pattern
print("\nSmall N results:")
for N, fN, gN in zip(small_N, small_f, small_g):
    print(f"N={N}: f={fN}, g={gN}")
"}

