# For small n, we can try all combinations using dynamic programming
# For n > 10, we'll use a different approach

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Small n brute force
    if n <= 10:
        # Use dynamic programming
        dp = [[0] * (n+1) for _ in range(n+1)]

        # Base cases: dp[i][i] = a[i-1]
        for i in range(1, n+1):
            dp[i][i] = a[i-1]

        # Fill dp table
        for length in range(2, n+1):
            for i in range(1, n - length + 2):
                j = i + length - 1
                for k in range(i, j):
                    # Combine from i to k, then k+1 to j
                    value = dp[i][k] + dp[k+1][j]
                    if dp[i][j] < value:
                        dp[i][j] = value

