{"code": "from functools import lru_cache

def solve():
    r, s, p = map(int, input().split())

    @lru_cache(maxsize=None)
    def dp(r, s, p):
        # Return tuple: (prob_rock_survives, prob_scissors_survives, prob_paper_survives)
        total = r*s + r*p + s*p

        # Base cases: only one species remaining
        if r == 0:
            return (0.0, 1.0, 1.0) if s > 0 else (0.0, 0.0, 1.0)
        if s == 0:
            return (1.0, 0.0, 1.0) if p > 0 else (1.0, 0.0, 0.0)
        if p == 0:
            return (1.0, 1.0, 0.0)

        # Transition probabilities
        prob_rock = 0
        prob_scissors = 0
        prob_paper = 0

        # Transition to (r-1, s, p) - rock kills scissors
        if r > 1:
            prs = r * s / total
            r1, s1, p1 = dp(r-1, s, p)
            prob_rock += prs * r1
            prob_scissors += prs * s1
            prob_paper += prs * p1

        # Transition to (r, s-1, p) - scissors kill paper
        if s > 1:
            rsp = r * p / total
            r2, s2, p2 = dp(r, s-1, p)
            prob_rock += rsp * r2
            prob_scissors += rsp * s2
            prob_paper += rsp * p2

        # Transition to (r, s, p-1) - paper kills rock
        if p > 1:
            spk = s * p / total
            r3, s3, p3 = dp(r, s, p-1)
            prob_rock += spk * r3
            prob_scissors += spk * s3
            prob_paper += spk * p3

        return (prob_rock, prob_scissors, prob_paper)

