import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        segments = []

        for _ in range(n):
            l = int(data[idx])
            r = int(data[idx + 1])
            idx += 2
            segments.append((l, r))

        # Check if there's a segment that intersects all others
        good = False
        for i, (l_i, r_i) in enumerate(segments):
            intersects_all = True
            for j, (l_j, r_j) in enumerate(segments):
                if i == j:
                    continue
                # Check if [l_i, r_i] intersects [l_j, r_j]
                if l_i <= r_j and r_i >= l_j:
                    continue
                intersects_all = False
                break
            if intersects_all:
                good = True
                break

        if good:
            results.append(0)
        else:
            # Need to delete some segments
            # We can keep the segment that intersects the most segments
            max_intersects = 0
            best_segment = -1

            for i, (l_i, r_i) in enumerate(segments):
                count = 0
                for j, (l_j, r_j) in enumerate(segments):
                    if i == j:
                        continue
                    if l_i <= r_j and r_i >= l_j:
                        count += 1
                if count > max_intersects:
                    max_intersects = count
                    best_segment = i

            # We need to delete n - 1 - max_intersects segments
            results.append(n - 1 - max_intersects)

    sys.stdout.write("\n".join(map(str, results)))

if __name__ == "__main__":
    solve()
