        # A substring of length k is balanced if it has exactly k/2 0s and k/2 1s

        # If we have a window of size k, we need:
        # - Number of fixed 0s ≤ k/2
        # - Number of fixed 1s ≤ k/2

        # Use sliding window
        count_0 = 0
        count_1 = 0

        # Initialize first window
        for i in range(k):
            if s[i] == '0':
                count_0 += 1
            elif s[i] == '1':
                count_1 += 1

        if count_0 > k // 2 or count_1 > k // 2:
            print("NO")
            continue

        # Slide the window
        for i in range(k, n):
            # Remove the leftmost character
            if s[i - k] == '0':
                count_0 -= 1
            elif s[i - k] == '1':
                count_1 -= 1

            # Add the new rightmost character
            if s[i] == '0':
                count_0 += 1
            elif s[i] == '1':
                count_1 += 1

            if count_0 > k // 2 or count_1 > k // 2:
