# Build tree
adj = [[] for _ in range(n + 1)]
for _ in range(n - 1):
    u, v = map(int, input().split())
    adj[u].append(v)
    adj[v].append(u)

# Compute depth and ancestor arrays for LCA
LOG = 20
up = [[0] * (n + 1) for _ in range(LOG)]
depth = [0] * (n + 1)

# DFS to compute depth and up arrays
visited = [False] * (n + 1)
def dfs(u, parent):
    visited[u] = True
    up[0][u] = parent
    for v in adj[u]:
        if not visited[v] and v != parent:
            depth[v] = depth[u] + 1
            dfs(v, u)

dfs(1, 0)

# Build LCA table
for k in range(1, LOG):
    for i in range(1, n + 1):
        up[k][i] = up[k - 1][up[k - 1][i]]

# LCA function
def lca(u, v):
    if depth[u] < depth[v]:
        u, v = v, u
    # Bring u up to depth of v
    for k in range(LOG - 1, -1, -1):
        if depth[u] - (1 << k) >= depth[v]:
            u = up[k][u]
    if u == v:
        return u
    for k in range(LOG - 1, -1, -1):
        if up[k][u] != up[k][v]:
            u = up[k][u]
            v = up[k][v]
    return up[0][u]

# Find LCA of all query vertices
def query_lca(query):
    lca_vertex = query[0]
    for v in query[1:]:
        lca_vertex = lca(lca_vertex, v)
    return lca_vertex

# Check if all vertices are in the subtree of root_query
# and the maximum depth difference is ≤ 1
