def solve(r, s, p):
    """Calculate the probabilities of each species surviving."""

    # Base cases
    # If only rocks are left
    if s == 0 and p == 0:
        return (1.0, 0.0, 0.0)
    # If only scissors are left
    if r == 0 and p == 0:
        return (0.0, 1.0, 0.0)
    # If only papers are left
    if r == 0 and s == 0:
        return (0.0, 0.0, 1.0)

    # Use memoization with lru_cache
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(r, s, p):
        # Base cases
        if s == 0 and p == 0:
            return (1.0, 0.0, 0.0)
        if r == 0 and p == 0:
            return (0.0, 1.0, 0.0)
        if r == 0 and s == 0:
            return (0.0, 0.0, 1.0)

        total = r + s + p

        if total <= 1:
            return (1.0, 0.0, 0.0)  # Only one individual left

        total_pairs = (total) * (total - 1)

        # Probability of each type of meeting
        prob_rock_scissors = (r * s) / total_pairs
        prob_scissors_paper = (s * p) / total_pairs
        prob_paper_rock = (p * r) / total_pairs

        # Transition probabilities
        rock_scissors_outcome = dp(r, s - 1, p)
        scissors_paper_outcome = dp(r, s, p - 1)
        paper_rock_outcome = dp(r - 1, s, p)

        # Weighted average of outcomes
        return (
            rock_scissors_outcome[0] * prob_rock_scissors +
            scissors_paper_outcome[0] * prob_scissors_paper +
            paper_rock_outcome[0] * prob_paper_rock,

            rock_scissors_outcome[1] * prob_rock_scissors +
            scissors_paper_outcome[1] * prob_scissors_paper +
            paper_rock_outcome[1] * prob_paper_rock,

            rock_scissors_outcome[2] * prob_rock_scissors +
            scissors_paper_outcome[2] * prob_scissors_paper +
            paper_rock_outcome[2] * prob_paper_rock
        )

    prob_r, prob_s, prob_p = dp(r, s, p)

    # Format with 12 decimal places
    return prob_r, prob_s, prob_p

# Read input
