q = int(input())

# Track current handle to next handle
handle_next = {}

for _ in range(q):
    old, new = input().split()

    # If the old handle already has a mapping, update it
    if old in handle_next:
        handle_next[old] = new
    else:
        handle_next[old] = new

# Now find all handles that are original (appear as old but not new)
original_handles = set()
final_handles = set()

for old, new in handle_next.items():
    original_handles.add(old)
    final_handles.add(new)

# Now we need to find the chain from original to final
# We can use a dictionary to map original to final
original_to_final = {}

# Start with original handles
for original in original_handles:
    current = original
    while current in handle_next:
        current = handle_next[current]
    original_to_final[original] = current

# Output results
print(len(original_to_final))
for old, new in original_to_final.items():
    print(f"{old} {new}")
"}

