    """Check if two different numbers a and b are friends."""
    g = gcd(a, b)
    x = g
    y = a // g
    z = b // g
    # Check triangle inequality: all three must be greater than the third
    # But wait, I need to check all three: x+y>z, x+z>y, y+z>x
    return x + y > z and x + z > y and y + z > x

