from functools import lru_cache

def solve(r, s, p):
    total = r + s + p

    @lru_cache(maxsize=None)
    def dp(rocks, scissors, papers):
        # Base cases: only one species remains
        if scissors == 0 and papers == 0:
            return (1.0, 0.0, 0.0)
        if rocks == 0 and papers == 0:
            return (0.0, 1.0, 0.0)
        if rocks == 0 and scissors == 0:
            return (0.0, 0.0, 1.0)

        # Calculate probabilities of each pair meeting
        prob = 0.0
        if rocks > 0 and scissors > 0:
            prob += rocks * scissors
        if scissors > 0 and papers > 0:
            prob += scissors * papers
        if rocks > 0 and papers > 0:
            prob += rocks * papers

        if prob == 0:
            return (0.0, 0.0, 0.0)

        # Normalize probabilities
        prob /= total

        # Rock-scissors meeting
        rocks_prob = 0.0
        scissors_prob = 0.0
        papers_prob = 0.0

        if rocks > 0 and scissors > 0:
            r1, s1, p1 = dp(rocks - 1, scissors, papers)
            r2, s2, p2 = dp(rocks, scissors - 1, papers)
            rocks_prob = (rocks * scissors / total) * r1 + (rocks * scissors / total) * r2
            scissors_prob = (rocks * scissors / total) * s1 + (rocks * scissors / total) * s2

        # Scissors-paper meeting
        if scissors > 0 and papers > 0:
            r1, s1, p1 = dp(rocks, scissors - 1, papers)
            r2, s2, p2 = dp(rocks, scissors, papers - 1)
            rocks_prob = (scissors * papers / total) * r1 + (scissors * papers / total) * r2
            scissors_prob = (scissors * papers / total) * s1 + (scissors * papers / total) * s2

        # Paper-rock meeting
        if rocks > 0 and papers > 0:
            r1, s1, p1 = dp(rocks - 1, scissors, papers)
            r2, s2, p2 = dp(rocks, scissors, papers - 1)
            rocks_prob = (rocks * papers / total) * r1 + (rocks * papers / total) * r2
            papers_prob = (rocks * papers / total) * p1 + (rocks * papers / total) * p2

        return (rocks_prob, scissors_prob, papers_prob)

    return dp(r, s, p)

# Read input
r, s, p = map(int, input().split())

# Calculate probabilities
probabilities = solve(r, s, p)

# Print with sufficient precision
print(f"{probabilities[0]:.15f} {probabilities[1]:.15f} {probabilities[2]:.15f}")
