import sys

def solve():
    data = sys.stdin.read().strip()
    if not data:
        return
    r = int(data)
    max_x = int(r**0.5) + 2  # add buffer
    for x in range(1, max_x + 1):
        temp = r - x*x - x - 1
        if temp <= 0:
            break
        if temp % (2*x) == 0:
            y = temp // (2*x)
            if y > 0:
                print(f"{x} {y}")
                return
    print("NO")

if __name__ == "__main__":
    solve()
"}

