l = int(input())

# If l is less than k, it's not a power (since k >= 2)
if l < k:
    print("NO")
else:
    count = 0
    # Keep dividing l by k as long as it's divisible by k
    while l % k == 0:
        l = l // k
        count += 1

    # If we ended up with 1, then l was a power of k
    if l == 1:
        print("YES")
        print(count - 1)
    else:
        print("NO")
