# Read input
class Solution:
    def solve(self):
        n = int(input())
        pattern = input().strip()

        # Check each Pokémon name
        for name in pokemon_names:
            if len(name) != n:
                continue

            # Check if the name matches the pattern
            matches = True
            for i in range(n):
                if pattern[i] != "." and pattern[i] != name[i]:
                    matches = False
                    break

            if matches:
                print(name)
                return

if __name__ == "__main__":
