def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

n = int(input())
points = list(map(int, input().split()))

points.sort()

# Calculate differences between consecutive points
if n < 2:
    print(0)
else:
    diffs = [points[i+1] - points[i] for i in range(n-1)]

    # Calculate GCD of all differences
    g = diffs[0]
    for diff in diffs[1:]:
        g = gcd(g, diff)

    # Calculate total points to add
    total = 0
    for diff in diffs:
        total += (diff // g) - 1

    print(total)
