def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        segments = []
        for _ in range(n):
            l = int(next(it))
            r = int(next(it))
            segments.append((l, r))

        max_intersections = 0
        for i, (li, ri) in enumerate(segments):
            cnt = 1  # Count the segment itself
            for j, (lj, rj) in enumerate(segments):
                if i == j:
                    continue
                # Check if segments intersect
                if max(li, lj) <= min(ri, rj):
                    cnt += 1
            max_intersections = max(max_intersections, cnt)

        print(n - max_intersections)

if __name__ == "__main__":
