import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        segments = []
        for _ in range(n):
            l = int(next(it))
            r = int(next(it))
            segments.append((l, r))

        # For each segment, count how many others it intersects
        # Then keep the segment with the most intersections
        max_intersections = 0
        for i, (li, ri) in enumerate(segments):
            cnt = 1  # Include itself
            for j, (lj, rj) in enumerate(segments):
                if i == j:
                    continue
                # Two segments [a, b] and [c, d] intersect if max(a,c) <= min(b,d)
                if max(li, lj) <= min(ri, rj):
                    cnt += 1
            max_intersections = max(max_intersections, cnt)

        # The minimum number of deletions is n - max_intersections
        print(n - max_intersections)

