def solve():
    s, k = input().split()
    k = int(k)

    # Read bonus table
    n = int(input())
    bonus_table = {}
    for _ in range(n):
        x, y, c = input().split()
        bonus_table[(x, y)] = int(c)

    N = len(s)
    INF = float('-inf')

    # dp[i][j][c]: max euphony from position i to end, with j changes made, ending with character c
    dp = [[{chr(ord('a') + i): INF for i in range(26)} for _ in range(k + 1)] for _ in range(N + 1)]

    # Base case: position N (no more pairs)
    for c in range(26):
        dp[N][0][chr(ord('a') + c)] = 0

    for i in range(N - 1, -1, -1):
        for j in range(k + 1):
            for c in range(26):
                # We are at position i with character c
                # What character d do we put at position i+1?
                if i + 1 < N:
                    next_char_orig = s[i + 1]

                    # Option 1: Keep the next character unchanged
                    if chr(ord('a') + c) == next_char_orig:
                        cost = 0
                    else:
                        cost = 1

                    if j + cost <= k:
                        bonus_value = bonus_table.get((chr(ord('a') + c), next_char_orig), 0)
                        dp[i + 1][j + cost][next_char_orig] = max(dp[i + 1][j + cost][next_char_orig], 
                                                           dp[i][j][chr(ord('a') + c)] + bonus_value)

                # Option 2: Change to a different character (if we have changes left)
                if i + 1 < N and j > 0:
                    next_char = chr(ord('a') + c)
                    next_char_orig = s[i + 1]

                    if next_char != next_char_orig:
                        bonus_value = bonus_table.get((chr(ord('a') + c), next_char), 0)
                        dp[i + 1][j - 1][next_char] = max(dp[i + 1][j - 1][next_char], 
                                                     dp[i][j][chr(ord('a') + c)] + bonus_value)

    # Find the maximum value among all possible states for position 0
    max_value = INF
    for j in range(k + 1):
        for c in range(26):
            max_value = max(max_value, dp[0][j][chr(ord('a') + c)])

    print(max_value)

solve()

