import sys

def intersects(a, b):
    return max(a[0], b[0]) <= min(a[1], b[1])

def solve():
    input = sys.stdin.read().split()
    data = iter(map(int, input))
    t = next(data)

    for _ in range(t):
        n = next(data)
        segments = []

        for _ in range(n):
            l = next(data)
            r = next(data)
            segments.append((l, r))

        max_intersections = 0

        for i in range(n):
            count = 0
            l_i, r_i = segments[i]

            for j in range(n):
                if i == j:
                    continue
                l_j, r_j = segments[j]
                if intersects((l_i, r_i), (l_j, r_j)):
                    count += 1

            max_intersections = max(max_intersections, count)

        # Answer: n - (max_intersections + 1)
        print(n - (max_intersections + 1))

if __name__ == "__main__":
    solve()
