def solve():
    t = int(input())
    for _ in range(t):
        n, x, y = map(int, input().split())
        b = list(map(int, input().split()))

        # Count frequency of each color
        from collections import defaultdict
        freq = defaultdict(int)
        for color in b:
            freq[color] += 1

        # Construct answer
        answer = []

        # First x positions: exact matches (we can just match first x colors)
        answer.extend(b[:x])

        # Remaining positions: need to match (y-x) different-index matches
        remaining_matches = y - x

        # Use colors that appear at least twice (we need at least one left after using one for exact match)
        for color, count in freq.items():
            if remaining_matches <= 0:
                break
            if count >= 2:
                answer.append(color)
                freq[color] -= 1  # One used for exact match, one used for different-index match
                remaining_matches -= 1

        # For remaining positions, we need to use unused colors
        while len(answer) < n:
            # Find a color that appears at least once (and hasn't been fully used)
            for color, count in freq.items():
                if count > 0:
                    answer.append(color)
                    freq[color] -= 1
                    break

        # Check if we actually got y matches
        # Calculate x (exact matches)
        exact = sum(1 for i in range(n) if answer[i] == b[i])
        # Calculate y (total matches)
        count_b = {}
        count_a = {}
        for i in range(n):
            count_b[b[i]] = count_b.get(b[i], 0) + 1
            count_a[answer[i]] = count_a.get(answer[i], 0) + 1

        y_calculated = sum(min(count_b.get(c, 0), count_a.get(c, 0)) for c in set(count_b))

        if exact == x and y_calculated == y:
            print("YES")
            print(' '.join(map(str, answer)))
        else:
            print("NO")

