import sys

def parse_line(line):
    """Parse a line to extract operator and parameters"""
    line = line.strip()
    if not line:
        return None, None, None

    # Check for try
    if line.startswith('try'):
        return 'try', None, None

    # Check for catch
    if line.startswith('catch'):
        parts = line.split('catch')
        if len(parts) < 2:
            return None, None, None
        content = parts[1].strip()

        # Extract exception type and message
        content = content.split(',', 1)
        if len(content) < 2:
            return None, None, None

        type_part = content[0].strip()
        message_part = content[1].strip()

        # Extract type from type_part
        if '(' not in type_part:
            return None, None, None
        type_part = type_part.split('(', 1)[1].strip().split(')', 1)[0].strip()

        # Extract message from message_part
        if '"' not in message_part:
            return None, None, None
        message_part = message_part.split('"', 1)[1].strip().split('"', 1)[0]

