def solve(r, s, p):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(r, s, p):
        # Check if only one species remains
        if r > 0 and s == 0 and p == 0:
            return (1.0, 0.0, 0.0)
        if r == 0 and s > 0 and p == 0:
            return (0.0, 1.0, 0.0)
        if r == 0 and s == 0 and p > 0:
            return (0.0, 0.0, 1.0)

        # Total number of individuals
        total = r + s + p

        # Total pairs that can meet
        total_pairs = total * (total - 1) / 2

        if total_pairs == 0:
            # No transitions possible, we're at a terminal state
            # This should only happen if only one species remains, which we already handle
            return dp(r, s, p)

        # Calculate probabilities of each transition
        rock_kills_scissors_prob = (r * s) / total_pairs
        scissors_kill_paper_prob = (s * p) / total_pairs
        paper_kills_rock_prob = (p * r) / total_pairs

        # Recursive probabilities
        prob_rock_kills_scissors = rock_kills_scissors_prob * dp(r-1, s, p)[0]
        prob_scissors_kill_paper = scissors_kill_paper_prob * dp(r, s-1, p)[1]
        prob_paper_kills_rock = paper_kills_rock_prob * dp(r, s, p-1)[2]

        # Normalize by the total probability of transitioning to a terminal state
        # (since one of these three must happen eventually)
        total_transition_prob = prob_rock_kills_scissors + prob_scissors_kill_paper + prob_paper_kills_rock

        return (prob_rock_kills_scissors / total_transition_prob,
                prob_scissors_kill_paper / total_transition_prob,
                prob_paper_kills_rock / total_transition_prob)

    return dp(r, s, p)

# Read input
line = input().strip()
r, s, p = map(int, line.split())

# Calculate probabilities
prob_rock, prob_scissors, prob_paper = solve(r, s, p)

# Print with 12 decimal places
print(f"{prob_rock:.12f} {prob_scissors:.12f} {prob_paper:.12f}")
"}

