import sys

def solve() -> None:
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return
    s_k = data[0].split()
    s = s_k[0]
    k = int(s_k[1])
    n = int(data[1]) if len(data) > 1 else 0
    bonus = [[-10**9] * 26 for _ in range(26)]
    for i in range(2, 2 + n):
        if i >= len(data):
            break
        line = data[i].split()
        if len(line) < 3:
            continue
        x, y, c = line[0], line[1], int(line[2])
        bonus[ord(x) - 97][ord(y) - 97] = c

    m = len(s)
    # dp[i][curr][rem] = max euphony after first i+1 characters (0-indexed), with i-th char = curr, remaining rem changes
    # i ranges 0..m-1
    INF = -10**18
    dp = [[[-10**18] * (k+1) for _ in range(26)] for _ in range(m)]

    # Initialize first character
    for curr in range(26):
        cost = 1 if curr != ord(s[0]) - 97 else 0
        if cost > k:
            continue
        for rem in range(k+1):
            if rem >= cost:
                dp[0][curr][rem] = -cost

    for i in range(1, m):
        for curr in range(26):
            cost_curr = 1 if curr != ord(s[i]) - 97 else 0
            for rem in range(k+1):
                if rem < cost_curr:
                    continue
                max_val = -10**18
                for prev in range(26):
                    cost_prev = 1 if prev != ord(s[i-1]) - 97 else 0
                    prev_rem = rem - cost_prev
                    if prev_rem >= 0 and dp[i-1][prev][prev_rem] != -10**18:
                        max_val = max(max_val, dp[i-1][prev][prev_rem])
                if max_val != -10**18:
                    dp[i][curr][rem] = max_val + bonus[prev][curr]  # prev chosen to maximize

    ans = max(dp[m-1][c][r] for c in range(26) for r in range(k+1) if dp[m-1][c][r] != -10**18)
    print(ans)

if __name__ == '__main__':
    solve()
