import sys

def solve():
    a = sys.stdin.readline().strip()
    k = int(sys.stdin.readline())

    MOD = 1000000007
    n = len(a)

    # dp[i] = number of ways for a string of length i
    # dp[0] = 1 if a[0] is '0' or '5', else 0
    # dp[i] = 2^i if a[i] is '0' or '5', else dp[i-1]

    dp = [0] * n

    for i in range(n):
        if a[i] in ('0', '5'):
            dp[i] = pow(2, i, MOD)
        else:
            if i > 0:
                dp[i] = dp[i-1]

    # Sum all dp values for the entire string
    ans = sum(dp) % MOD

    print(ans)

if __name__ == "__main__":
    solve()
"}

