import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    b_list = list(map(int, data[1:1+n]))

    evens = []
    odds = []

    for b in b_list:
        if b % 2 == 0:
            evens.append(b)
        else:
            odds.append(b)

    if len(odds) > 0 and len(evens) > 0:
        # Remove the smaller group
        if len(odds) < len(evens):
            remove_list = odds
        else:
            remove_list = evens

        print(len(remove_list))
        print(' '.join(map(str, remove_list)))
    else:
        # All elements have the same parity
        print(0)

if __name__ == "__main__":
    solve()
"}

