import sys

def is_supersequence(s, t):
    # Check if s is a subsequence of t
    if not s:
        return True
    if not t:
        return False

    i = 0  # index for s
    j = 0  # index for t

    while i < len(s) and j < len(t):
        if s[i] == t[j]:
            i += 1
        j += 1

    return i == len(s)

def is_possible(s, t):
    # Check if t could be printed by typing s
    # t must be at least as long as s and have at least as many of each character
    if len(t) < len(s):
        return False

    # Count character occurrences in both s and t
    s_count = {}
    t_count = {}

    for c in s:
        s_count[c] = s_count.get(c, 0) + 1

    for c in t:
        t_count[c] = t_count.get(c, 0) + 1

    # Check if t has at least as many of each character as s
    for c, count in s_count.items():
        if t_count.get(c, 0) < count:
            return False

    # Check if s is a subsequence of t
    return is_supersequence(s, t)

def main():
    data = sys.stdin.read().strip().split('\n')
    n = int(data[0])
    idx = 1

    results = []
    for _ in range(n):
        s = data[idx]
        t = data[idx + 1]
        idx += 2

        if is_possible(s, t):
            results.append("YES")
        else:
            results.append("NO")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    main()
