        new_dp = dp.copy()
        for state in range(8):
            if dp[state] < float('inf'):
                new_state = state | mask
                if new_dp[new_state] > dp[state] + price:
                    new_dp[new_state] = dp[state] + price
        dp = new_dp
    if dp[7] < float('inf'):
        print(dp[7])
    else:
        print(-1)

