    # Odd length palindromes (centered at i)
    for (start, end) in expand(s, i, i):
        palindromes.append((start, end))
    # Even length palindromes (centered between i and i+1)
    for (start, end) in expand(s, i, i + 1):
        palindromes.append((start, end))

# Count valid pairs
