def count_palindrome_pairs(s):
    n = len(s)

    # Find all palindromic substrings
    is_palindrome = [[False] * n for _ in range(n)]

    # Single character palindromes
    for i in range(n):
        is_palindrome[i][i] = True

    # Length 2 palindromes
    for i in range(n - 1):
        if s[i] == s[i + 1]:
            is_palindrome[i][i + 1] = True

    # Longer palindromes
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # Count palindromic substrings
    palindromes = []
    for i in range(n):
        for j in range(i, n):
            if is_palindrome[i][j]:
                palindromes.append((i + 1, j + 1))  # 1-indexed

    # Count non-overlapping pairs
    count = 0
    for i in range(len(palindromes)):
        for j in range(i + 1, len(palindromes)):
            # Get positions of first palindrome
            a, b = palindromes[i]
            # Get positions of second palindrome
            x, y = palindromes[j]

            # Check if they don't overlap
            if b < x:
                count += 1

    return count

s = input().strip()
